removed=set(before)-set(after);added=set(after)-set(before);changed={u for u in before.keys()&after.keys()if before[u]!=after[u]}
assert len(removed)==7 and len(added)==41 and len(changed)==6
oldfp={o['uuid']:o for o in source['footprints']};newfp={o['uuid']:o for o in current['footprints']};changedfp={u for u in oldfp if oldfp[u]!=newfp[u]}
assert {oldfp[u]['ref']for u in changedfp}=={'R7','R8','C69'}
